#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
render_line_v5.py 修复包 v6.1
=============================
修复回填 bug：趋势窗口锚点从「全局最新日期」改为「目标日及之前」
解决：① 回填历史日期 KeyError  ② 趋势图混入未来数据
用法: python3 deploy_render_fix.py
"""
import base64, os
TARGET = "/root/bi_dashboard/v5scripts/render_line_v5.py"
# 先备份旧版
if os.path.exists(TARGET):
    import shutil
    shutil.copy(TARGET, TARGET + '.bak_before_fix')
    print(f'  已备份旧版 → {TARGET}.bak_before_fix')
BLOB = ""
with open(TARGET, 'wb') as f:
    f.write(base64.b64decode(BLOB))
print(f'  已写入修复版 → {TARGET}')
print()
print('='*50)
print('✅ render_line_v5.py 已更新为修复版 v6.1')
print('   修复：回填 KeyError + 趋势图未来数据污染')
print('='*50)
